# ------------------------------------------------------- Clearance Practice 2
S2 = '1. A single 250-mg oral dose of an antibiotic is given to a young man (age 32 years, creatinine clearance 122 mL/min, 78 kg). From the literature, the drug is known to have an apparent VD equal to 21% of body weight and an elimination half-life of 2 hours. The dose is normally 90% bioavailable. Urinary excretion of the unchanged drug is equal to 70% of the absorbed dose.'
clt2 = 0.21 * 78 * 0.693 / 2
p2 = [
 num('ws4-2-1a', stem=S2 + ' What is the total body clearance for this drug? (Give it in L/hr.)', units='L/hr', ans=5.676, calc=clt2, **M4, sub='clcalc', skill='clearance', concept='clt-from-vd-k',
     steps=[('unit', 'VD = (0.21)(78 kg) = 16.38 L', 'A volume given as a percentage of body weight is read as litres per kilogram: 21% of 78 kg is 0.21 × 78 = 16.38 L.'),
            ('setup', 'ClT = VD × k, k = {{frac:0.693|2 hr}}', 'Total clearance is the elimination rate constant times the volume of distribution: reciprocal hours times litres gives L/hr.'),
            ('algebra', 'ClT = (16.38 L)(0.3465 hr⁻¹) = 5.676 L/hr', 'k = {{frac:0.693|2 hr}} = 0.3465 hr⁻¹; (16.38 L)(0.3465 hr⁻¹) = 5.676 L/hr, litres times reciprocal hours giving litres per hour. Total clearance ClT depends on VD and k alone, so the 250 mg dose, the 90% bioavailability and the 70% urinary share are not used here.')],
     teach=T_CLT_K, setup=dict(eq='cl-k-vd', pre=['thalf-first'], why='The stem gives "apparent VD equal to 21% of body weight" and "an elimination half-life" and asks "the total body clearance", so the clearance block. VD and t½ are given, ClT is asked, which is Cl = k × VD. Hinge: k = 0.693/t½ first, because the line wants k, not the half-life.'), givens=[['D0', '250-mg', 'not needed: ClT depends on VD and k alone'], ['age', '32 years', 'not needed'], ['CrCl', '122 mL/min', 'not needed for the number'], ['weight', '78 kg', 'VD = 0.21 × 78 = 16.38 L'], ['VD', '21% of body weight', '0.21 L per kg, times 78 kg, multiplies k'], ['t½', '2 hours', 'gives k = {{frac:0.693|2}} = 0.3465 hr⁻¹'], ['F', '90% bioavailable', 'not needed'], ['fe', '70% of the absorbed dose', 'not needed: the total, not the renal part, is asked']],
     check=dict(t='With a 2-hour half-life about a third of the 16.38 L is cleared each hour (k = 0.3465 hr⁻¹), so ClT is about 5.676 L/hr, a little over a third of 16.38.', lo=0), cite=f'{CL2}, page 1, part 1a'),
 num('ws4-2-1a2', stem=S2 + ' What is the total body clearance for this drug, in mL/min?', units='mL/min', ans=94.59, calc=clt2 * 1000 / 60, **M4, sub='clcalc', skill='clearance', concept='l-hr-to-ml-min',
     steps=[('unit', '(5.676 L/hr)({{frac:1000 mL|1 L}})({{frac:1 hr|60 min}}) = 94.59 mL/min', 'Litres become millilitres (× 1000) and hours become minutes (÷ 60), so total clearance is in the same unit as CrCl.')],
     teach=T_CLT_K, setup=dict(eq='cl-k-vd', pre=['thalf-first'], why='The stem asks "the total body clearance" again, "in mL/min", so the same clearance line, Cl = k × VD, with k = 0.693/t½ first. The working then converts L/hr to mL/min (× 1000, ÷ 60), which is a unit change, not another equation.'), givens=[['D0', '250-mg', 'not needed: ClT depends on VD and k alone'], ['age', '32 years', 'not needed'], ['CrCl', '122 mL/min', 'not needed for the number; a comparison for later'], ['weight', '78 kg', 'VD = 0.21 × 78 = 16.38 L'], ['VD', '21% of body weight', '0.21 L per kg, times 78 kg, multiplies k'], ['t½', '2 hours', 'gives k = {{frac:0.693|2}} = 0.3465 hr⁻¹, so ClT = 5.676 L/hr'], ['F', '90% bioavailable', 'not needed'], ['fe', '70% of the absorbed dose', 'not needed: the total is asked']],
     check=dict(t='One L/hr is 1000 mL in 60 min, about 17 mL/min; 5.676 L/hr is a little under six of those, so a value near 95 mL/min fits, and 94.59 mL/min does.', lo=0), cite=f'{CL2}, page 1, part 1a'),
 num('ws4-2-1b', stem=S2 + ' What is the renal clearance for this drug?', units='mL/min', ans=66.22, calc=0.7 * clt2 * 1000 / 60, **M4, sub='clcalc', skill='clearance', concept='clr-from-fe',
     steps=[('setup', 'ClR = fe × ClT, fe = 0.7', 'Urinary excretion of unchanged drug is 70% of the absorbed dose, so fe = 0.7 and renal clearance is 0.7 of the total.'),
            ('algebra', 'ClR = (0.7)(94.59 mL/min) = 66.22 mL/min', 'Using the unrounded total clearance, 94.594 mL/min, gives 66.22; the rounded 94.59 gives 66.21. Both are the same answer.')],
     teach=T_SPLIT, note='0.7 × 94.59 gives 66.21; her key prints 66.22 because it carries the unrounded 94.594. Either is accepted.', setup=dict(eq='clr', pre=['thalf-first', 'cl-k-vd'], why='The stem says "Urinary excretion of the unchanged drug is equal to 70% of the absorbed dose" and asks "the renal clearance", so the renal block. fe = 0.7 and ClT are the inputs, ClR is asked, which is ClR = fe × ClT. Hinge: ClT = k × VD with k = 0.693/t½, from part 1a.'), givens=[['D0', '250-mg', 'not needed'], ['age', '32 years', 'not needed'], ['CrCl', '122 mL/min', 'not needed for the number; ClR is compared with it afterwards'], ['weight', '78 kg', 'VD = 0.21 × 78 = 16.38 L'], ['VD', '21% of body weight', 'with k gives ClT = 5.676 L/hr = 94.59 mL/min'], ['t½', '2 hours', 'gives k = {{frac:0.693|2}} = 0.3465 hr⁻¹'], ['F', '90% bioavailable', 'not needed'], ['fe', '70% of the absorbed dose', 'fe = 0.7 multiplies ClT']],
     check=dict(t='Seven tenths of 94.59 mL/min is a little under 70: 66.22 mL/min. ClR cannot exceed the total clearance, 94.59 mL/min, and it is below the CrCl of 122 mL/min, so filtration with reabsorption.', lo=0, hi=94.59), cite=f'{CL2}, page 1, part 1b'),
 mc('ws4-2-1c', stem=S2 + ' What is the probable mechanism for renal clearance of this drug?', **M4, sub='renalmech', skill='apply', concept='mechanism-from-clr',
    options=[('Filtered at the glomerulus and partially reabsorbed', True, 'Renal clearance, 66.22 mL/min, is less than the creatinine clearance, 122 mL/min, the estimate of GFR. Less than filtration means some filtered drug returns to the blood.'),
             ('Filtered and actively secreted', False, 'Picking this reads a drug that is largely renal (fe = 0.7) as one the kidney handles actively. Active secretion adds drug to the urine on top of filtration, so renal clearance would exceed the GFR, estimated at 122 mL/min; here ClR is 66.22 mL/min, below it.'),
             ('Filtered only, nothing else', False, 'This answer takes filtration as the only possible mechanism when ClR is below the GFR. Filtration alone clears unbound drug at the glomerular filtration rate, about 122 mL/min for this patient, so a renal clearance of 66.22 mL/min means some filtered drug was reabsorbed, not filtered only.'),
             ('Cleared mainly by the liver', False, 'Picking this reads a renal clearance below the GFR as a sign that the kidney is a minor route. fe = 0.7 means 70% of the absorbed dose leaves in urine unchanged, so the kidney is the main route; the question asks how the kidney handles the drug, and a ClR below GFR means reabsorption.')],
    steps=[
           ('setup', 'fe = 0.70: urinary excretion of unchanged drug is 70% of the absorbed dose', 'fe is the fraction of the absorbed dose that reaches the urine unchanged. It says the kidney handles 70% of the elimination and nothing about how: a drug can be 70% renal by filtration alone, by filtration with reabsorption, or with secretion.'),
           ('setup', 'VD = (0.21)(78 kg) = 16.38 L; k = {{frac:0.693|2 hr}} = 0.3465 hr⁻¹; ClT = kVD = (0.3465)(16.38) = 5.676 L/hr', 'The mechanism is read from renal clearance, which is a share of total clearance, so total clearance comes first: the volume scaled from 21% of body weight and the rate constant from the 2-hour half-life.'),
           ('unit', 'ClT = 5.676 L/hr × {{frac:1000 mL|1 L}} × {{frac:1 hr|60 min}} = 94.59 mL/min', 'The creatinine clearance, the GFR estimate, is in mL/min, so total clearance is put in the same unit before the renal share is taken; L cancels against mL per L and hr against hr per min.'),
           ('algebra', 'ClR = fe × ClT = 0.70 × 94.59 mL/min = 66.22 mL/min', 'Renal clearance is the renal fraction of total clearance: the same fe that was only a fraction in step 1 now scales a clearance, a number with units that can be set against the filtration rate. The unrounded 94.594 gives 66.22; the rounded total gives 66.21.'),
           ('setup', 'Compare: ClR = 66.22 mL/min against the GFR, the creatinine clearance of 122 mL/min (about 120); 66.22 is below it', 'Filtration alone would clear unbound drug at the GFR. A renal clearance below it means some filtered drug is taken back into the blood, so the mechanism is filtration with partial reabsorption; above the GFR would mean active secretion adds drug to the urine.')],
    givens=[['D0', '250-mg', 'not needed: clearance does not depend on the dose'], ['age', '32 years', 'not needed: the creatinine clearance is given, so no Cockcroft-Gault'], ['CrCl', '122 mL/min', 'the GFR estimate that ClR is compared with'], ['weight', '78 kg', 'scales the volume: (0.21)(78) = 16.38 L'], ['VD', '21% of body weight', '0.21 L per kg, inside ClT = kVD'], ['t½', '2 hours', 'gives k = {{frac:0.693|2}} = 0.3465 hr⁻¹'], ['F', '90%', 'not needed: fe is already a fraction of the absorbed dose'], ['fe', '70% of the absorbed dose', 'fe = 0.70, scales ClT to ClR']],
    check=dict(t='fe = 0.70 alone cannot name the mechanism: a drug with the same fe but a much shorter half-life would have a renal clearance above the GFR and be secreted. Only ClR in mL/min set against the GFR, 122 mL/min for this patient, decides, and 66.22 is below it.'),
    teach=T_MECH, cite=f'{CL2}, page 1, part 1c')]
S22 = '2. Estimate the creatinine clearance of a 37-year-old female who weighs 143 lb, serum creatinine of 0.6 mg/dL, and stands 5’6” tall.'
ibw = 45.5 + 2.3 * 6
p2.append(num('ws4-2-2', stem=S22, units='mL/min', ans=120.2, calc=0.85 * (140 - 37) * ibw / (72 * 0.6), **M4, sub='crclcalc', skill='crcl', concept='cockcroft-gault',
    steps=[('unit', '5 ft 6 in: 6 inches over 5 ft', 'The ideal body weight equation counts only the inches above 5 ft (60 in). A height of 5 ft 6 in is already in feet and inches, so no conversion from centimetres is needed and the inches over 5 ft are the 6 in read straight off the height.'),
           ('algebra', 'IBW = 45.5 + 2.3(6) = 59.3 kg', 'The female form starts at 45.5 kg. The 143 lb total body weight is not used, because her keys use ideal body weight.'),
           ('setup', 'CrCl = 0.85 × {{frac:(140 − 37)(59.3)|(72)(0.6)}}', 'The Cockcroft-Gault equation estimates creatinine clearance from age, ideal body weight and serum creatinine SCr: (140 − age)(IBW) over 72 × SCr. The patient is female, and women produce less creatinine per kilogram of body weight, so the male estimate is multiplied by 0.85.'),
           ('round', 'CrCl = 120.2 mL/min', '(103)(59.3) = 6107.9 on top and (72)(0.6) = 43.2 below; {{frac:6107.9|43.2}} = 141.4, and 0.85 × 141.4 = 120.2 mL/min. CrCl is reported in mL/min, the unit of the glomerular filtration rate it estimates, to one decimal place as her key does.')],
    teach=T_CRCL, setup=dict(eq='crcl', pre=['ibw-female'], why='The stem says "Estimate the creatinine clearance" of a "female" and gives age, serum creatinine and height, so the Cockcroft-Gault line with the 0.85 factor. CrCl is asked from age, IBW and SCr. IBW first, from the inches over 5 ft with the female constant 45.5, because the line wants ideal body weight.'), givens=[['age', '37-year-old', '140 − 37 = 103 on top'], ['sex', 'female', 'IBW starts at 45.5 kg and the result is multiplied by 0.85'], ['weight', '143 lb', 'not needed: her keys use ideal body weight'], ['SCr', '0.6 mg/dL', 'the denominator, 72 × 0.6 = 43.2'], ['height', '5’6”', '6 inches over 5 ft, so IBW = 45.5 + 2.3 × 6 = 59.3 kg']],
     check=dict(t='A 37-year-old woman with a low SCr of 0.6 mg/dL has normal kidneys, so a CrCl near or above the usual 120 mL/min fits; 120.2 mL/min does. Forgetting the 0.85 gives a value about a sixth too high.'), cite=f'{CL2}, page 1, problem 2'))
