# ------------------------------------------------------- Clearance Practice 4
S4 = '1. A new antibiotic is excreted by the kidney. The apparent volume of distribution is 25L in the normal adult. The clearance of this drug is 300 mL/min.'
p4 = [
 mc('ws4-4-1a', stem=S4 + ' a. What is the probable mechanism of renal excretion of this drug?', **M4, sub='renalmech', skill='apply', concept='mechanism-from-clr',
    options=[('Active secretion', True, 'Clearance, 300 mL/min, is well above GFR (about 120 mL/min). Only secretion can clear more plasma than is filtered.'),
             ('Filtration only', False, 'Picking this reads any renally excreted drug as simply filtered. Filtration alone clears unbound drug at the glomerular filtration rate, about 120 mL/min; a renal clearance of 300 mL/min is 2.5 times that, more than filtration can supply, so a second process must add drug to the urine.'),
             ('Filtration with partial reabsorption', False, 'This answer reads the comparison with GFR in the wrong direction. Reabsorption returns filtered drug from the tubule to the blood, so it lowers renal clearance below the GFR of about 120 mL/min; a clearance of 300 mL/min is above GFR, which reabsorption cannot produce.'),
             ('Hepatic metabolism', False, 'Picking this treats the 300 mL/min as a total clearance with a hepatic share to find. The stem says the drug is excreted by the kidney, so the 300 mL/min is renal clearance, and the question is which renal process produces it; metabolism is not a mechanism of renal excretion.')],
    steps=[
           ('setup', 'The drug is excreted by the kidney, so the 300 mL/min clearance is its renal clearance; reference GFR about 120 mL/min', 'Nothing else eliminates the drug, so total clearance and renal clearance are the same number. Filtration alone would clear unbound drug at the glomerular filtration rate, so 300 mL/min is read against about 120 mL/min.'),
           ('algebra', '{{frac:300 mL/min|120 mL/min}} = 2.5; 300 − 120 = 180 mL/min beyond filtration', 'The renal clearance is two and a half times the filtration rate: each minute 180 mL of plasma more than filtration can account for is cleared of the drug, so a second process is adding drug to the tubular fluid.'),
           ('setup', 'Compare: ClR = 300 mL/min is above 120 mL/min, so filtration with active tubular secretion', 'Above the GFR means a process adds drug to the lumen beyond filtration: active secretion. Reabsorption could only pull the value below 120 mL/min, and filtration alone would sit at about 120, so 300 mL/min is filtration plus secretion.')],
    givens=[['VD', '25L', 'not needed for the mechanism; used for the half-life in part b'], ['ClT', '300 mL/min', 'equals ClR, since excretion is renal; compared with about 120 mL/min']],
    check=dict(t='Reabsorption can only lower renal clearance below the filtration rate, and filtration alone cannot exceed about 120 mL/min, so 300 mL/min, 2.5 times the GFR, can come from nothing but filtration plus active secretion. The 25 L volume does not enter.'),
    teach=T_MECH, cite=f'{CL4}, page 1, part 1a'),
 num('ws4-4-1b', stem=S4 + ' b. What is the usual t½ for this drug?', units='min', ans=58, calc=0.693 * 25000 / 300, **M4, sub='clcalc', skill='krate', concept='thalf-from-cl-vd',
     steps=[('unit', 'VD = 25 L = 25,000 mL', 'Clearance is given in mL/min, so the volume is converted to mL as well; then mL cancels and the half-life comes out in minutes.'),
            ('algebra', 't½ = {{frac:(0.693)(25,000 mL)|300 mL/min}} = 58 min', '(0.693)(25,000 mL) = 17,325 mL on top; dividing by Cl = 300 mL/min, the millilitres cancel and the reciprocal minutes invert to minutes: {{frac:17,325 mL|300 mL/min}} = 57.75 min, reported as 58 min. Half of the drug in the body is cleared every 58 minutes.')],
     teach=T_THALF_CL, setup=dict(eq='thalf-cl-vd', pre=[], why='The stem gives "The apparent volume of distribution" and "The clearance of this drug" and asks "the usual t½", so the clearance block. VD and Cl are given, t½ is asked, which is t½ = 0.693 VD/ClT. No hinge: the line already combines Cl = k VD with t½ = 0.693/k; the volume is put in mL to match mL/min.'), givens=[['route', 'excreted by the kidney', 'not needed for the number'], ['VD', '25L', 'put in mL, 25,000 mL, the numerator of 0.693 VD'], ['Cl', '300 mL/min', 'the denominator']],
     check=dict(t='Cl of 300 mL/min empties the 25,000 mL once in {{frac:25,000|300}} min, and a half-life is 0.693 of that turnover time, so a little under an hour: 58 min fits. The unit is minutes because Cl is per minute.', lo=0), cite=f'{CL4}, page 1, part 1b'),
 num('ws4-4-1c', stem=S4 + ' c. What would be the new t½ for this drug in an adult with partial renal failure whose clearance of the antibiotic was 125 mL/min?', units='min', ans=139, calc=0.693 * 25000 / 125, **M4, sub='clcalc', skill='krate', concept='thalf-from-cl-vd',
     steps=[('algebra', 't½ = {{frac:(0.693)(25,000 mL)|125 mL/min}} = 139 min', 't½ = {{frac:0.693 VD|Cl}}: VD, the volume of distribution, is unchanged, so (0.693)(25,000 mL) = 17,325 mL on top, and with Cl lowered to 125 mL/min, {{frac:17,325 mL|125 mL/min}} = 138.6 min, reported as 139 min. Clearance fell by the factor {{frac:300|125}} = 2.4, so the half-life rose 2.4 times, from 58 to 139 min.')],
     teach=T_THALF_CL, setup=dict(eq='thalf-cl-vd', pre=[], why='The stem asks "the new t½" in "partial renal failure" where "clearance of the antibiotic was 125 mL/min", so the clearance block. VD and the lower Cl are given, t½ is asked, which is t½ = 0.693 VD/ClT. No hinge: the same line as part b with 125 mL/min in place of 300.'), givens=[['route', 'excreted by the kidney', 'not needed for the number'], ['VD', '25L', 'unchanged: 25,000 mL, the numerator of 0.693 VD'], ['Cl', '300 mL/min', 'not needed: replaced by the lower clearance'], ['Cl new', '125 mL/min', 'the new denominator']],
     check=dict(t='Clearance fell from 300 to 125 mL/min, less than half, so the half-life more than doubles from the part b value; 139 min fits, and a value shorter than part b means the ratio was inverted.', lo=0), cite=f'{CL4}, page 1, part 1c')]
S42 = '2. Estimate the CrCl of a 42-year-old female who weighs 82kg, SCr =0.9 mg/dL, and 170 cm tall.'
ibw = 45.5 + 2.3 * 7
p4.append(num('ws4-4-2', stem=S42, units='mL/min', ans=79.19, calc=0.85 * (140 - 42) * ibw / (72 * 0.9), **M4, sub='crclcalc', skill='crcl', concept='cockcroft-gault',
    steps=[('unit', '170 cm ÷ 2.54 = 66.93 in, taken as 7 in over 5 ft', 'Height in centimetres is divided by 2.54 cm per inch: {{frac:170 cm|2.54 cm/in}} = 66.93 in, the centimetres cancelling. The ideal body weight equation counts inches above 60 in (5 ft), so 66.93 − 60 = 6.93, rounded to a whole 7 in before the IBW is computed, as her keys do.'),
           ('algebra', 'IBW = 45.5 + 2.3(7) = 61.6 kg', 'The female form starts at 45.5 kg. The 82 kg total body weight is not used, because her keys use ideal body weight.'),
           ('setup', 'CrCl = 0.85 × {{frac:(140 − 42)(61.6)|(72)(0.9)}} = 79.19 mL/min', 'The Cockcroft-Gault equation estimates creatinine clearance from age, ideal body weight and serum creatinine SCr: (98)(61.6) = 6036.8 over (72)(0.9) = 64.8 gives 93.16 mL/min; the patient is female, and women produce less creatinine per kilogram, so 0.85 × 93.16 = 79.19 mL/min.')],
    teach=T_CRCL, note='With 6.93 inches instead of 7, IBW is 61.44 kg and CrCl 78.98 mL/min; both are accepted.', setup=dict(eq='crcl', pre=['ibw-female'], why='The stem says "Estimate the CrCl" of a "female" with age, SCr and height in cm, so the Cockcroft-Gault line with the 0.85 factor. CrCl is asked from age, IBW and SCr. IBW first, from the inches over 5 ft after cm are divided by 2.54, because the line wants ideal body weight, not 82 kg.'), givens=[['age', '42-year-old', '140 − 42 = 98 on top'], ['sex', 'female', 'IBW starts at 45.5 kg and the result is multiplied by 0.85'], ['weight', '82kg', 'not needed: her keys use ideal body weight'], ['SCr', '0.9 mg/dL', 'the denominator, 72 × 0.9 = 64.8'], ['height', '170 cm', '{{frac:170|2.54}} = 66.93 in, 7 in over 5 ft, so IBW = 61.6 kg']],
     check=dict(t='With IBW 61.6 kg the male estimate is 140 − 42 times 61.6 over 72 × 0.9, a little over 90 mL/min; 0.85 of that is near 79 mL/min, so 79.19 fits. Skipping the 0.85 gives a value too high by about a sixth.'), cite=f'{CL4}, page 1, problem 2'))
chain('ws4-p4', src='practice', module=4, name='Clearance & Elimination Practice 4', setup='A secreted antibiotic (VD 25 L, Cl 300 then 125 mL/min), then a CrCl estimate', parts=p4)

# ------------------------------------------------------- Single Oral Practice 1
O1 = 'Daily-Practice-Singler-Oral-1---Solutions.pdf'
O2 = 'Daily-Practice-Single-Oral-2---Solutions.pdf'
O3 = 'Daily-Practice-Single-Oral-3-Solutions.pdf'
M5 = dict(module=5, lecture='L06', topic='oral')
SO1 = ('Procainamide is used for the treatment of ventricular tachyarrhythmia. It is administered intravenously, intramuscularly, and orally (Canada), and its therapeutic range is 4 to 8 mcg/mL. '
       'When a 750 mg dose is administered intravenously to a normal healthy subject: the elimination half-life is 3 hr; the apparent volume of distribution is 140 L or 2 L/kg; 65% is excreted in the urine; 35% is metabolized. '
       'When a 250 mg tablet is administered orally to a normal healthy subject: the absorption rate constant is 2.8 hr⁻¹; fraction of dose absorbed is 85.54%. Determine the following from the data provided: ')
k = 0.693 / 3; ka = 2.8; F = 0.8554; V = 140
tm = ln(ka / k) / (ka - k); cm = lambda D, t, kk: F * D * ka / (V * (ka - kk)) * (e(-kk * t) - e(-ka * t))
k14 = 0.693 / 14; tm14 = ln(ka / k14) / (ka - k14)
q = []
q.append(num('ws5-1-1t', stem=SO1 + '1. Total body clearance (and renal and metabolic clearance). What is the total body clearance?', units='L/hr', ans=32.34, calc=140 * k, **M5, sub='conc', skill='clearance', concept='clt-from-vd-k',
    steps=[('setup', 'ClT = VD × k = (140 L)({{frac:0.693|3 hr}}) = 32.34 L/hr', 'Total clearance ClT = VD × k, the volume of distribution times the elimination rate constant: each hour the fraction k of the drug in the 140 L is cleared. k = {{frac:0.693|3 hr}} = 0.231 hr⁻¹ from the IV half-life, and (140 L)(0.231 hr⁻¹) = 32.34 L/hr, litres times reciprocal hours.')], teach=T_CLT_K, setup=dict(eq='cl-k-vd', pre=['thalf-first'], why='The stem says a dose "is administered intravenously" with "the elimination half-life is 3 hr" and "the apparent volume of distribution is 140 L", and asks "the total body clearance", so the clearance block. VD and t½ are given, ClT is asked, which is Cl = k × VD. Hinge: k = 0.693/t½ first, because the line wants k.'), givens=[['range', '4 to 8 mcg/mL', 'not needed for the number'], ['D0 IV', '750 mg', 'not needed: ClT depends on VD and k alone'], ['t½', '3 hr', 'gives k = {{frac:0.693|3}} = 0.231 hr⁻¹'], ['VD', '140 L or 2 L/kg', '140 L multiplies k'], ['fe', '65%', 'not needed: the total is asked'], ['metabolized', '35%', 'not needed'], ['ka', '2.8 hr⁻¹', 'not needed'], ['F', '85.54%', 'not needed']],
     check=dict(t='A 3 hr half-life clears a little under a quarter of the 140 L each hour; a quarter of 140 is 35, so a ClT a little under 35, 32.34 L/hr, fits.', lo=0), cite=f'{O1}, page 1, part 1'))
q.append(num('ws5-1-1r', stem=SO1 + '1. Total body clearance, renal clearance and metabolic clearance. What is the renal clearance?', units='L/hr', ans=21.02, calc=140 * k * 0.65, **M5, sub='conc', skill='clearance', concept='clr-from-fe',
    steps=[('setup', 'ClR = fe × ClT = (32.34 L/hr)(0.65) = 21.02 L/hr', 'The stem says 65% is excreted in the urine unchanged, so fe = 0.65 and the renal clearance is 0.65 of the total.')], teach=T_SPLIT, setup=dict(eq='clr', pre=['thalf-first', 'cl-k-vd'], why='The stem says "65% is excreted in the urine" and asks "the renal clearance", so the renal block. fe = 0.65 and ClT are the inputs, ClR is asked, which is ClR = fe × ClT. Hinge: ClT = k × VD with k = 0.693/t½ first, because the line wants the total clearance.'), givens=[['range', '4 to 8 mcg/mL', 'not needed for the number'], ['D0 IV', '750 mg', 'not needed: ClT depends on VD and k alone'], ['t½', '3 hr', 'gives k = {{frac:0.693|3}} = 0.231 hr⁻¹'], ['VD', '140 L or 2 L/kg', 'with k gives ClT = 140 × 0.231 = 32.34 L/hr'], ['fe', '65%', 'fe = 0.65 multiplies ClT'], ['metabolized', '35%', 'not needed: the renal part is asked'], ['ka', '2.8 hr⁻¹', 'not needed'], ['F', '85.54%', 'not needed']],
     check=dict(t='Sixty-five percent of 32.34 L/hr is about two thirds of it, near 21, so 21.02 L/hr; ClR must be below the total, 32.34 L/hr.', lo=0, hi=32.34), cite=f'{O1}, page 1, part 1'))
q.append(num('ws5-1-1m', stem=SO1 + '1. Total body clearance, renal clearance and metabolic clearance. What is the metabolic clearance?', units='L/hr', ans=11.32, calc=140 * k * 0.35, **M5, sub='conc', skill='clearance', concept='clh-from-clt',
    steps=[('setup', 'ClH = (32.34 L/hr)(0.35) = 11.32 L/hr', 'The stem says 35% of the dose is metabolized, so the metabolic (hepatic) clearance is 0.35 of the total clearance.')], teach=T_SPLIT, setup=dict(eq='clh', pre=['thalf-first', 'cl-k-vd'], why='The stem says "35% is metabolized" and asks "the metabolic clearance", so the renal block. fe = 0.65 and ClT are the inputs, ClH is asked, which is ClH = (1 − fe) × ClT with 1 − fe = 0.35. Hinge: ClT = k × VD with k = 0.693/t½ first, because the line wants the total clearance.'), givens=[['range', '4 to 8 mcg/mL', 'not needed for the number'], ['D0 IV', '750 mg', 'not needed: ClT depends on VD and k alone'], ['t½', '3 hr', 'gives k = {{frac:0.693|3}} = 0.231 hr⁻¹'], ['VD', '140 L or 2 L/kg', 'with k gives ClT = 140 × 0.231 = 32.34 L/hr'], ['fe', '65%', 'not needed directly: 1 − fe = 0.35 is the metabolic share'], ['metabolized', '35%', '0.35 multiplies ClT'], ['ka', '2.8 hr⁻¹', 'not needed'], ['F', '85.54%', 'not needed']],
     check=dict(t='Thirty-five percent of 32.34 L/hr is about a third, near 11, so 11.32 L/hr; the metabolic part is below the renal part because 35% is less than 65%, and below the total.', lo=0, hi=32.34), cite=f'{O1}, page 1, part 1'))
q.append(num('ws5-1-2t', stem=SO1 + '2. Time to peak following the oral administration of a 250 mg dose.', units='hr', ans=0.97, calc=tm, **M5, sub='peak', skill='oral', concept='tmax-oral',
    steps=[('setup', 'k = {{frac:0.693|3 hr}} = 0.231 hr⁻¹', 'k, the elimination rate constant, is {{frac:0.693|t½}} = {{frac:0.693|3 hr}} = 0.231 hr⁻¹, the fraction of the drug in the body eliminated per hour. tmax, the time of the peak, is the moment the absorption rate equals the elimination rate, so it depends on k and on ka, the absorption rate constant, 2.8 hr⁻¹.'),
           ('algebra', 'tmax = {{frac:ln(2.8/0.231)|(2.8 − 0.231) hr⁻¹}} = 0.97 hr', 'ka/k is a ratio of two rate constants, a pure number, and dividing its log by (ka − k) in hr⁻¹ gives hours.')], teach=T_TMAX, setup=dict(eq='tmax', pre=['thalf-first'], why='The stem says "administered orally" of "a 250 mg tablet" with "the absorption rate constant is 2.8 hr⁻¹" and asks "Time to peak", so the single oral dose block. ka and t½ are given, tmax is asked, which is tmax = ln(ka/k)/(ka − k). Hinge: k = 0.693/t½ first, because the line wants k, not the half-life.'), givens=[['range', '4 to 8 mcg/mL', 'not needed for the number'], ['D0 IV', '750 mg', 'not needed: tmax depends on ka and k alone'], ['t½', '3 hr', 'gives k = {{frac:0.693|3}} = 0.231 hr⁻¹'], ['VD', '140 L or 2 L/kg', 'not needed'], ['fe', '65%', 'not needed: the total is asked'], ['metabolized', '35%', 'not needed'], ['ka', '2.8 hr⁻¹', 'in ln({{frac:ka|k}}) on top and in ka − k below'], ['F', '85.54%', 'not needed'], ['D0 oral', '250 mg', 'not needed: the dose does not move the peak time']],
     check=dict(t='Absorption (ka = 2.8 hr⁻¹) is about 12 times faster than elimination (k = 0.231 hr⁻¹), so the peak comes early, well within the first half-life of 3 hr; 0.97 hr fits.', lo=0), cite=f'{O1}, page 1, part 2'))
q.append(num('ws5-1-2c', stem=SO1 + '2. Maximum plasma concentration following the oral administration of a 250 mg dose.', units='mg/L', ans=1.22, calc=cm(250, tm, k), **M5, sub='peak', skill='oral', concept='cmax-oral',
    steps=[('setup', 'Cmax = {{frac:F ka D0|VD(ka − k)}} (e^(−k tmax) − e^(−ka tmax))', 'The single oral dose equation gives Cp at any time as {{frac:F ka D0|VD(ka − k)}} (e^(−kt) − e^(−ka t)); F = 0.8554 is the fraction absorbed, ka = 2.8 hr⁻¹ the absorption rate constant, k = 0.231 hr⁻¹ the elimination rate constant. Cmax is that equation at t = tmax = 0.97 hr.'),
           ('algebra', 'Cmax = {{frac:(0.8554)(250 mg)(2.8 hr⁻¹)|140 L (2.8 − 0.231) hr⁻¹}} (e^(−(0.97)(0.231)) − e^(−(0.97)(2.8)))', 'Reciprocal hours cancel between ka and (ka − k), and mg ÷ L leaves mg/L, so the peak comes out as a concentration.'),
           ('round', 'Cmax = 1.22 mg/L', 'The peak is reported to two decimal places in mg/L, which is the same as mcg/mL for comparison with the range.')], teach=T_CMAX, setup=dict(eq='oral-cp', pre=['thalf-first', 'tmax'], why='The stem says "oral administration of a 250 mg dose" and asks "Maximum plasma concentration", so the single oral dose block. F, ka, D0, VD and k are the inputs, Cmax is asked, which is the oral Cp line at t = tmax. Hinges: k = 0.693/t½, then tmax = ln(ka/k)/(ka − k).'), givens=[['range', '4 to 8 mcg/mL', 'not needed for the number; the peak is compared with it afterwards'], ['D0 IV', '750 mg', 'not needed: the oral dose is asked about'], ['t½', '3 hr', 'gives k = {{frac:0.693|3}} = 0.231 hr⁻¹'], ['VD', '140 L or 2 L/kg', '140 L in the denominator'], ['fe', '65%', 'not needed: the total is asked'], ['metabolized', '35%', 'not needed'], ['ka', '2.8 hr⁻¹', 'in the coefficient and in e^(−ka tmax)'], ['F', '85.54%', 'F = 0.8554 in the numerator'], ['D0 oral', '250 mg', 'the dose in the numerator']],
     check=dict(t='All of the absorbed dose, 0.8554 × 250 mg, in 140 L would give between 1 and 2 mg/L; the peak lies below that ceiling because elimination runs during absorption, so 1.22 mg/L fits and is below the 4 mcg/mL floor of the range.', lo=0, hi=1.53), cite=f'{O1}, page 1, part 2'))
q.append(num('ws5-1-2d', stem=SO1 + '2. Maximum plasma concentration following the oral administration of a 500 mg dose.', units='mg/L', ans=2.44, calc=cm(500, tm, k), **M5, sub='peak', skill='oral', concept='cmax-dose-proportional',
    steps=[('setup', 'Same equation, D0 = 500 mg; tmax is still 0.97 hr', 'The same oral equation with D0 = 500 mg in the coefficient {{frac:F ka D0|VD(ka − k)}}. tmax = {{frac:ln(ka/k)|ka − k}} holds ka = 2.8 hr⁻¹ and k = 0.231 hr⁻¹ but no dose, so the 500 mg dose peaks at the same 0.97 hr as the 250 mg dose; only the coefficient changes.'),
           ('algebra', 'Cmax = {{frac:(0.8554)(500 mg)(2.8 hr⁻¹)|140 L (2.8 − 0.231) hr⁻¹}} (e^(−(0.97)(0.231)) − e^(−(0.97)(2.8))) = 2.44 mg/L', 'With first-order kinetics the peak is proportional to the dose, so twice the dose gives twice the peak, 2.44 mg/L.')], teach=T_CMAX, setup=dict(eq='oral-cp', pre=['thalf-first', 'tmax'], why='The stem says "oral administration of a 500 mg dose" and asks "Maximum plasma concentration", so the single oral dose block. The same F, ka, VD and k with D0 = 500 mg are the inputs, Cmax is asked, which is the oral Cp line at t = tmax. Hinges: k = 0.693/t½ and tmax, which holds no dose.'), givens=[['range', '4 to 8 mcg/mL', 'not needed for the number'], ['D0 IV', '750 mg', 'not needed'], ['t½', '3 hr', 'gives k = {{frac:0.693|3}} = 0.231 hr⁻¹'], ['VD', '140 L or 2 L/kg', '140 L in the denominator'], ['fe', '65%', 'not needed: the total is asked'], ['metabolized', '35%', 'not needed'], ['ka', '2.8 hr⁻¹', 'in the coefficient and in e^(−ka tmax)'], ['F', '85.54%', 'F = 0.8554 in the numerator'], ['D0 oral', '500 mg', 'the dose in the numerator, twice the 250 mg tablet']],
     check=dict(t='Twice the 250 mg dose gives twice the part 2 peak at the same tmax, 0.97 hr, so 2.44 mg/L; the whole absorbed dose in 140 L would be about 3 mg/L, a ceiling the peak stays under.', lo=0, hi=3.06), cite=f'{O1}, page 1, part 2'))
