# ------------------------------------------------------- Single Oral Practice 3
SO3 = 'A 1000-mg single dose of a drug is given orally to a patient. Eighty percent of the dose is absorbed, the apparent volume of distribution is 24 L, and the half-lives of elimination and absorption are 10 and 0.25 hours, respectively. Determine the following: '
k3, ka3 = 0.0693, 2.772
A3 = 0.8 * ka3 * 1000 / (24 * (ka3 - k3)); tm3 = ln(ka3 / k3) / (ka3 - k3)
cp3 = lambda t: A3 * (e(-k3 * t) - e(-ka3 * t))
q = []
q.append(num('ws5-3-1', stem=SO3 + '1. Total body clearance', units='L/hr', ans=1.6632, calc=24 * 0.693 / 10, **M5, sub='conc', skill='clearance', concept='clt-from-vd-k',
    steps=[('setup', 'ClT = (24 L)({{frac:0.693|10 hr}}) = 1.6632 L/hr', 'Total clearance is the elimination rate constant times the volume of distribution: reciprocal hours times litres gives L/hr.')], teach=T_CLT_K, setup=dict(eq='cl-k-vd', pre=['thalf-first'], why='The stem says a dose "is given orally" with "the apparent volume of distribution is 24 L" and "the half-lives of elimination and absorption", and asks "Total body clearance", so the clearance block. VD and t½ are given, ClT is asked, which is Cl = k × VD. Hinge: k = 0.693/t½ first, with the 10 hr elimination half-life.'), givens=[['D0', '1000-mg', 'not needed: clearance depends on VD and k alone'], ['F', 'Eighty percent', 'not needed: clearance does not depend on F'], ['VD', '24 L', 'multiplies k'], ['t½', '10 hours', 'gives k = {{frac:0.693|10}} = 0.0693 hr⁻¹'], ['t½a', '0.25 hours', 'not needed: absorption does not set clearance']],
     check=dict(t='A 10 hour half-life clears about 7% of the volume each hour (0.693 over 10), and 7% of 24 L is about 1.7 L, so 1.6632 L/hr fits.', lo=0), cite=f'{O3}, page 1, part 1'))
